function queryRiskHistory(){$("#titleBack").click(function(){$("#titleBack").attr("href","javascript:redirectUrl('/WeixinService/business/user/riskLevel.shtml')")});$(".header .top-a h2").html("历史测评记录");loadRiskHistroy()}function loadRiskHistroy(){$.ajax({async:!1,url:"/WeixinService/business/queryUserRiskHistory.xhtml",dataType:"json",cache:!1,type:"POST",error:function(){show_tips("网络繁忙，请稍后再试。")},success:function(n){var r,t,i,u;if(!!n){for(r=n,t="",i=0;i<r.length;i++)u=r[i],t+='<tr class="risk_tr">',t+='<td class="risk_td1">'+u.riskEvalDate+"<\/td>",t+='<td class="risk_td2">'+u.riskLevel+"<\/td><\/tr>";$("#riskData").html(t)}}})}function backRiskPage(){window.location.href="/WeixinService/business/user/riskLevel.shtml"}